import{_ as a,C as r,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const w=JSON.parse('{"title":"Warehouses","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/warehouses/warehouses.md","filePath":"master/supply-chain/inventories/warehouses/warehouses.md","lastUpdated":1791902625000}'),h={name:"master/supply-chain/inventories/warehouses/warehouses.md"};function l(d,e,g,u,p,c){const o=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="warehouses" tabindex="-1">Warehouses <a class="header-anchor" href="#warehouses" aria-label="Permalink to &quot;Warehouses&quot;">​</a></h1><p>A warehouse is the site where you keep stock. Each warehouse has a name, a short name and an optional address. It also decides how many steps goods take when they arrive and when they leave. Your first warehouse already exists, so you only add one when you run a second site.</p><blockquote><p><strong>In simple words:</strong> A warehouse is a building with its own code, plus a choice of how many handling steps receipts and deliveries use.</p></blockquote><p>Open <code>Inventory → Configurations → Warehouse Management → Warehouses</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Settings</strong> block on the warehouse form needs a setting turned on.</p><ol><li>Go to <code>Inventory → Settings → Manage Warehouses</code>.</li><li>Turn on <strong>Multi Steps Routes</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol><p>Turn on <strong>Locations</strong> in the same page. See <a href="./../get-started/inventory-settings.html">Inventory settings</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows the columns <strong>Name</strong>, <strong>Short Name</strong>, <strong>Company</strong> and <strong>Address</strong>. The dev database has one warehouse: <strong>My Company</strong>, short name <strong>WH</strong>.</p>',10)),s(o,{src:"/images1/inventory/wh_list.png",alt:"Warehouses list with My Company, short name WH, tabs All and Archived"}),e[1]||(e[1]=t('<p>Two tabs sit above the list:</p><ul><li><strong>All:</strong> every active warehouse.</li><li><strong>Archived:</strong> warehouses you deleted. Deleting only archives the record. Open the tab to restore a warehouse or remove it for good.</li></ul><p>You can group the list by <strong>Company</strong>, <strong>Created At</strong> or <strong>Updated At</strong>, and filter by <strong>Company</strong>.</p><h2 id="create-a-warehouse" tabindex="-1">Create a warehouse <a class="header-anchor" href="#create-a-warehouse" aria-label="Permalink to &quot;Create a warehouse&quot;">​</a></h2><ol><li>Click <strong>New Warehouse</strong>.</li><li>Fill the <strong>General</strong> section.</li><li>Choose the reception and delivery steps in the <strong>Settings</strong> section.</li><li>Click <strong>Create</strong>.</li></ol>',5)),s(o,{src:"/images1/inventory/wh_create.png",alt:"Create Warehouse form with name Central Warehouse, short name CW and One step selected for both incoming and outgoing shipments (not yet saved)"}),e[2]||(e[2]=t('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The full name, for example <strong>Central Warehouse</strong>. Required.</li><li><strong><em>Short Name:</em></strong> A code such as <strong>CW</strong>. Required.</li><li><strong><em>Company:</em></strong> Fixed to your current company. You cannot change it here.</li><li><strong><em>Address:</em></strong> The contact record for the site. Click <strong>+</strong> to create a contact on the spot.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The short name becomes the first part of every location and document name, such as <strong>CW/Stock</strong> and <strong>CW/IN/1</strong>. Choose it with care before you start moving stock.</p></div><h3 id="settings-1" tabindex="-1">Settings <a class="header-anchor" href="#settings-1" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>The <strong>Shipment Management</strong> fieldset has two radio lists.</p><p><strong><em>Incoming Shipments:</em></strong> the default route for goods that arrive.</p><table tabindex="0"><thead><tr><th>Option</th><th>Label</th><th>What happens</th></tr></thead><tbody><tr><td>One step</td><td>Receive and Store (One step)</td><td>Goods go straight to <strong>Stock</strong>.</td></tr><tr><td>Two steps</td><td>Receive then Store (Two steps)</td><td>Goods go to <strong>Input</strong>, then to <strong>Stock</strong>.</td></tr><tr><td>Three steps</td><td>Receive, Quality Control, then Store (Three steps)</td><td>Goods go to <strong>Input</strong>, then <strong>Quality Control</strong>, then <strong>Stock</strong>.</td></tr></tbody></table><p><strong><em>Outgoing Shipments:</em></strong> the default route for goods that leave.</p><table tabindex="0"><thead><tr><th>Option</th><th>Label</th><th>What happens</th></tr></thead><tbody><tr><td>One step</td><td>Deliver (One step)</td><td>Goods leave straight from <strong>Stock</strong>.</td></tr><tr><td>Two steps</td><td>Pick then Deliver (Two steps)</td><td>Goods move to <strong>Output</strong>, then leave.</td></tr><tr><td>Three steps</td><td>Pick, Pack, then Deliver (Three steps)</td><td>Goods move to <strong>Packing Zone</strong>, then <strong>Output</strong>, then leave.</td></tr></tbody></table><p>The default for both lists is <strong>One step</strong>, as the create form shows. Extra steps add extra locations and extra documents, but give you more control.</p><p>A third fieldset, <strong>Resupply Management</strong>, appears when the Manufacturing app is installed. Its <strong>Manufacturing</strong> radio sets how many steps manufacturing uses. See <a href="./../../manufacturing/workflows/manufacturing-orders.html">Manufacturing orders</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The dev warehouse uses three steps for reception, delivery and manufacturing. That is why you see documents such as <strong>WH/PICK</strong>, <strong>WH/PACK</strong> and <strong>WH/QC</strong>. See <a href="./../routes/three-step-flow.html">Three-step flow</a>.</p></div><h2 id="view-a-warehouse" tabindex="-1">View a warehouse <a class="header-anchor" href="#view-a-warehouse" aria-label="Permalink to &quot;View a warehouse&quot;">​</a></h2><p>Open a warehouse to see three tabs at the top: <strong>View</strong>, <strong>Edit</strong> and <strong>Routes</strong>. <strong>View</strong> shows the warehouse name, code, company, address and chosen steps. <strong>Routes</strong> opens a page titled <strong>Manage My Company Routes</strong>. It lists the routes the warehouse created for those steps and has an <strong>Add Route</strong> button. See <a href="./../routes/">Routes</a>.</p>',14)),s(o,{src:"/images1/inventory/wh_view_routes.png",alt:"Manage My Company Routes page listing Pick components/manufacture, Deliver in 3 steps and Receive in 3 steps"}),e[3]||(e[3]=t('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Edit:</strong> change the name, address or steps. Existing documents keep working.</li><li><strong>Delete:</strong> a button on the <strong>Edit</strong> tab. It archives the warehouse and moves it to the <strong>Archived</strong> tab.</li><li><strong>Restore</strong> and <strong>Force delete:</strong> available on archived rows.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./locations.html">Locations</a></li><li><a href="./operation-types.html">Operation types</a></li><li><a href="./../routes/one-step-flow.html">One-step flow</a></li><li><a href="./../routes/two-step-flow.html">Two-step flow</a></li></ul>',4))])}const v=a(h,[["render",l]]);export{w as __pageData,v as default};
